import json
p='app.json'; d=json.load(open(p))
e=d['expo']
e['ios'].pop('buildNumber')
e['ios']['config']={'usesNonExemptEncryption': False}
a=e['android']; a.pop('versionCode')
e['android']={'package':'com.acmeapps.tidy', **a}
json.dump(d,open(p,'w'),indent=2); open(p,'a').write('\n')
EOF
